def topo_order(deps):
    remaining = {t: set(u) for t, u in deps.items()}
    order = []
    while remaining:
        ready = sorted(t for t, u in remaining.items() if not u)
        if not ready:
            raise ValueError("cycle")
        t = ready[0]
        order.append(t)
        del remaining[t]
        for u in remaining.values():
            u.discard(t)
    return order

def run_dag(deps, fail_counts, retries, delay):
    states, clock = {}, 0
    for t in topo_order(deps):
        if any(states[u] != "success" for u in deps[t]):
            states[t] = "upstream_failed"
            continue
        k = fail_counts.get(t, 0)
        if k > retries:
            states[t] = "failed"
            clock += delay * retries
        else:
            states[t] = "success"
            clock += delay * k
    return states, clock

deps = {"extract": [], "transform": ["extract"], "load": ["transform"]}
states, clock = run_dag(deps, {"extract": 2, "transform": 5}, 3, 60)
print(states)
print("clock", clock)
